#!/usr/bin/env python3
"""Build the Denton County Civic GPS package from the exact reconstructed v0.6.0 runtime."""
from __future__ import annotations

import base64
import hashlib
import shutil
import zlib
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GPS = ROOT / "civic_gps"
PARTS = ROOT / "civic_gps_runtime_parts"
ZIP_PATH = ROOT / "civic_gps_runtime.zip"
EXPECTED_OLD_SHA = "fef242729e6e2efeb0a92c9f81bd19c31a3533ac2b3d44d4e5024ba392ee487b"
EXPECTED_NEW_SHA = "66f876c59809849b36ab837e942ac2465e2c32936cf44f1cbe8aa65795ee04c7"

REGISTRY_Z = ""
RELEASE_Z = ""
README_Z = ""


def decode(value: str) -> bytes:
    return zlib.decompress(base64.b64decode(value))


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def build_zip() -> str:
    if not GPS.is_dir():
        raise SystemExit("civic_gps runtime must already be reconstructed")
    (GPS / "registry.json").write_bytes(decode(REGISTRY_Z))
    (GPS / "civic_gps_denton_county_v0.1.json").write_bytes(decode(RELEASE_Z))
    (GPS / "README.md").write_bytes(decode(README_Z))

    with zipfile.ZipFile(ZIP_PATH, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as zf:
        for path in sorted(GPS.iterdir(), key=lambda p: p.name):
            if not path.is_file():
                continue
            info = zipfile.ZipInfo(f"civic_gps/{path.name}", date_time=(2026, 8, 7, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.create_system = 3
            info.external_attr = 0o100644 << 16
            zf.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)

    digest = sha256(ZIP_PATH)
    if digest != EXPECTED_NEW_SHA:
        raise SystemExit(f"new runtime SHA mismatch: expected {EXPECTED_NEW_SHA}, got {digest}")

    PARTS.mkdir(exist_ok=True)
    for old in PARTS.glob("part.*"):
        old.unlink()
    blob = ZIP_PATH.read_bytes()
    for i in range(0, len(blob), 8000):
        (PARTS / f"part.{i // 8000:02d}").write_bytes(blob[i:i + 8000])
    rebuilt = b"".join(p.read_bytes() for p in sorted(PARTS.glob("part.*")))
    if hashlib.sha256(rebuilt).hexdigest() != EXPECTED_NEW_SHA:
        raise SystemExit("split-part reconstruction failed")
    return digest


if __name__ == "__main__":
    current = sha256(ZIP_PATH) if ZIP_PATH.exists() else None
    if current not in {EXPECTED_OLD_SHA, EXPECTED_NEW_SHA}:
        raise SystemExit(f"unexpected starting runtime SHA: {current}")
    digest = build_zip()
    print(f"PACKAGED Denton County runtime: {digest}")
    print(f"parts: {[(p.name, p.stat().st_size) for p in sorted(PARTS.glob('part.*'))]}")
